    void AddField(System.Windows.Controls.Panel body,string key,string label,string help){body.Children.Add(new TextBlock{Text=label+"\n"+help,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,2)});var input=new TextBox();fields.Add(key,input);body.Children.Add(input);input.TextChanged+=(_,_)=>Invalidate();}
    void ClearView(){view.Panels=null;view.Visibility=Visibility.Collapsed;view.InvalidateVisual();}
    void ConfirmationChanged(){if(suppressInvalidation)return;epoch++;active?.Cancel();ClearView();status.Text="Onay değişti; gerekirse incelemeyi yeniden başlatın.";}
    void Invalidate(){if(suppressInvalidation)return;epoch++;active?.Cancel();ClearView();if(confirmed.IsChecked==true)confirmed.IsChecked=false;status.Text="Girdi değişti; kontrol ve onayı yenileyin.";}
    void SetUnit(string? value){unitInternal=true;try{unit.SelectedItem=value;}finally{unitInternal=false;}}
    void UnitChanged()
    {
        if(unitInternal)return;var target=unit.SelectedItem as string;
        if(unitPromptActive){SetUnit(appliedUnit);epoch++;active?.Cancel();status.Text="Birim isteği değişti; önceki dönüşüm iptal edildi.";return;}
        if(appliedUnit is null){appliedUnit=target;Invalidate();return;}
        string from=appliedUnit;if(target==from)return;
        if(target is not ("mm" or "cm")){SetUnit(from);status.Text="Geçerli birim seçin.";return;}
        var original=fields.ToDictionary(x=>x.Key,x=>x.Value.Text,StringComparer.Ordinal);string oldTolerance=tolerance.Text;
        if(original.Values.All(x=>x.Length==0)&&oldTolerance.Length==0){appliedUnit=target;Invalidate();return;}
        SetUnit(from);epoch++;active?.Cancel();long before=epoch;
        var beforeModel=model.SelectedItem as string;var beforeSample=sample.SelectedItem as string;var beforeConfirm=confirmed.IsChecked;var beforeSymmetry=symmetry.IsChecked;var beforeReference=sameReference.IsChecked;
        UnitPlan plan;try{plan=UnitConversion.Prepare(original,oldTolerance,from,target);}catch(Exception e) when(e is InvalidOperationException or OverflowException or ArgumentException){status.Text="Birim değiştirilmedi. Dolu alanları ve toleransı açık, geçerli ve kayıpsız dönüştürülebilir biçimde düzeltin.";return;}
        bool approve;unitPromptActive=true;try{approve=ConfirmUnitForTest?.Invoke(from,target)??(MessageBox.Show(this,$"Dolu uzunluklar ve tolerans {from} → {target} olarak dönüştürülecek; omuz açısı değişmeyecek. Devam edilsin mi?","Birim değişimi",MessageBoxButton.YesNo,MessageBoxImage.Warning,MessageBoxResult.No)==MessageBoxResult.Yes);}catch{status.Text="Onay alınamadı; birim ve değerler korunuyor.";return;}finally{unitPromptActive=false;}
        if(!approve){status.Text="Birim dönüşümü iptal edildi; değerler korunuyor.";return;}
        if(epoch!=before||appliedUnit!=from||!StringComparer.Ordinal.Equals(unit.SelectedItem as string,from)||!StringComparer.Ordinal.Equals(beforeModel,model.SelectedItem as string)||!StringComparer.Ordinal.Equals(beforeSample,sample.SelectedItem as string)||beforeConfirm!=confirmed.IsChecked||beforeSymmetry!=symmetry.IsChecked||beforeReference!=sameReference.IsChecked||oldTolerance!=tolerance.Text||original.Any(x=>fields[x.Key].Text!=x.Value)){status.Text="Form değişti; birim dönüşümü iptal edildi.";return;}
        bool success=false;suppressInvalidation=true;try{int index=0;foreach(var (key,value) in plan.Fields){fields[key].Text=value;UnitApplyForTest?.Invoke(++index);}tolerance.Text=plan.Tolerance;UnitApplyForTest?.Invoke(++index);SetUnit(target);appliedUnit=target;success=true;}
        catch{foreach(var (key,value) in original)fields[key].Text=value;tolerance.Text=oldTolerance;SetUnit(from);appliedUnit=from;status.Text="Dönüşüm tamamlanamadı; önceki değerler korundu.";}
        finally{suppressInvalidation=false;}
        if(success){Invalidate();status.Text="Dolu uzunluklar ve tolerans yeni birime dönüştürüldü; onayı yenileyin.";}
    }
    internal void RunLocalReview()
    {
        epoch++;active?.Cancel();ClearView();try{var values=fields.ToDictionary(x=>x.Key,x=>x.Value.Text,StringComparer.Ordinal);var report=LocalWaistReview.Inspect(model.SelectedItem as string,unit.SelectedItem as string,confirmed.IsChecked==true,symmetry.IsChecked==true,sameReference.IsChecked==true,tolerance.Text,values);status.Text=report.Text;}
        catch(InvalidOperationException e){status.Text=e.Message;}
        catch(Exception e) when(e is FormatException or OverflowException or ArgumentException){status.Text="Yerel kontrol yapılamadı. Ölçüleri, ortak bel referansını, onayları ve açık toleransı kontrol edin.";}
    }
    internal bool TryFillSample(Func<bool> confirmReplacement)
    {
        if(sample.SelectedItem is not string id||unit.SelectedItem is not string u){status.Text="Önce birim ve sentetik örnek seçin.";return false;}
        long before=epoch;var beforeModel=model.SelectedItem as string;var beforeSample=sample.SelectedItem as string;var beforeUnit=unit.SelectedItem as string;var beforeConfirm=confirmed.IsChecked;var beforeSymmetry=symmetry.IsChecked;var beforeReference=sameReference.IsChecked;var beforeTolerance=tolerance.Text;
        var beforeFields=fields.ToDictionary(x=>x.Key,x=>x.Value.Text,StringComparer.Ordinal);
        if(beforeFields.Values.Any(x=>x.Length!=0))
        {
            if(!confirmReplacement()){status.Text="Sentetik örnek yüklemesi iptal edildi; alanlar korunuyor.";return false;}
            if(epoch!=before||!StringComparer.Ordinal.Equals(beforeModel,model.SelectedItem as string)||!StringComparer.Ordinal.Equals(beforeSample,sample.SelectedItem as string)||!StringComparer.Ordinal.Equals(beforeUnit,unit.SelectedItem as string)||beforeConfirm!=confirmed.IsChecked||beforeSymmetry!=symmetry.IsChecked||beforeReference!=sameReference.IsChecked||beforeTolerance!=tolerance.Text||beforeFields.Any(x=>fields[x.Key].Text!=x.Value))
            {status.Text="Form, model veya birim değişti; sentetik örnek yüklemesi iptal edildi.";return false;}
        }
        var values=Contract.SampleInput(id,u);foreach(var (key,value) in values)fields[key].Text=value;status.Text="Sentetik örnek dolduruldu; model, simetri ve ölçüleri ayrıca onaylayın.";return true;
    }
    internal bool StartsEmpty=>model.SelectedIndex==-1&&unit.SelectedIndex==-1&&confirmed.IsChecked!=true&&sameReference.IsChecked!=true&&tolerance.Text.Length==0&&fields.Count==26&&fields.Values.All(x=>x.Text.Length==0);
