    internal void ResetUnitForTest()=>unit.SelectedItem="mm";
    internal void ChangeAndRestoreForTest(){fields["upper.waist"].Text="998";fields["upper.waist"].Text="999";}
    internal void ChangeModelAndRestoreForTest(){model.SelectedIndex=-1;model.SelectedItem=Contract.Model;}
    internal void ChangeToleranceAndRestoreForTest(){tolerance.Text="1";tolerance.Text="";}
    internal string WaistForTest=>fields["upper.waist"].Text;
    internal bool IsBaseSampleForTest=>Contract.SampleInput("synthetic-base","mm").All(x=>fields[x.Key].Text==x.Value);
    internal void PrepareLocalForTest(){symmetry.IsChecked=true;sameReference.IsChecked=true;tolerance.Text="0";confirmed.IsChecked=true;}
    internal string StatusForTest=>status.Text;
    internal bool HasBothColorsForTest(){view.Measure(new Size(1000,600));view.Arrange(new Rect(0,0,1000,600));view.UpdateLayout();var bitmap=new RenderTargetBitmap(1000,600,96,96,PixelFormats.Pbgra32);bitmap.Render(view);var data=new byte[1000*600*4];bitmap.CopyPixels(data,4000,0);bool blue=false,orange=false;for(int i=0;i<data.Length;i+=4){if(data[i]>120&&data[i+1]<180&&data[i+2]<110&&data[i]>data[i+1])blue=true;if(data[i]<80&&data[i+1]>60&&data[i+1]<180&&data[i+2]>180)orange=true;}return blue&&orange;}
}
internal static class Program
{
    [STAThread]static int Main(string[] args){if(args.SequenceEqual(new[]{"--verify"})){try{var r=VerifyAsync().GetAwaiter().GetResult();var app=new Application();var w=new ResearchWindow();if(!w.StartsEmpty)throw new Exception("form prefilled");w.ConfirmForTest();w.ShowForTest(r);if(!w.VisibleForTest||!w.HasBothColorsForTest())throw new Exception("preview missing or blank");w.EditForTest();if(w.VisibleForTest||w.ConfirmedForTest)throw new Exception("stale view or confirmation");w.ConfirmForTest();w.ShowForTest(r);w.SelectSampleForTest();if(w.VisibleForTest||w.ConfirmedForTest)throw new Exception("stale sample selection");VerifyFill();VerifyLocal();VerifyUnits();Console.WriteLine("PASS: exact local comparison, explicit numeric rule, atomic unit conversion and synthetic-only worker gate; no window shown");return 0;}catch(Exception e){Console.Error.WriteLine("FAIL: "+e.Message);return 1;}}return new Application().Run(new ResearchWindow());}
    static void VerifyFill(){var blank=new ResearchWindow();blank.PrepareBlankFillForTest();bool asked=false;if(!blank.TryFillSample(()=>{asked=true;return true;})||asked||!blank.IsBaseSampleForTest)throw new Exception("blank fill");var w=new ResearchWindow();w.PrepareFillForTest();w.ConfirmUnitForTest=(_,_)=>false;if(w.TryFillSample(()=>false)||w.WaistForTest!="999")throw new Exception("cancel overwrote input");if(w.TryFillSample(()=>{w.ChangeUnitForTest();return true;})||w.WaistForTest!="999")throw new Exception("unit change overwrote input");w.ResetUnitForTest();if(w.TryFillSample(()=>{w.ChangeAndRestoreForTest();return true;})||w.WaistForTest!="999")throw new Exception("reentrant change overwrote input");if(w.TryFillSample(()=>{w.ChangeModelAndRestoreForTest();return true;})||w.WaistForTest!="999")throw new Exception("model change overwrote input");if(w.TryFillSample(()=>{w.ChangeToleranceAndRestoreForTest();return true;})||w.WaistForTest!="999")throw new Exception("tolerance change overwrote input");if(!w.TryFillSample(()=>true)||!w.IsBaseSampleForTest||w.ConfirmedForTest)throw new Exception("confirmed fill failed");}
    static void VerifyLocal(){var fields=Contract.SampleInput("synthetic-base","mm");var result=LocalWaistReview.Inspect(Contract.Model,"mm",true,true,true,"0",fields);if(result.UpperBodyWaistMm!=740m||result.LowerBodyArcSumMm!=720m||result.DifferenceMm!=20m||result.Comparison!=InputComparison.OutsideDeclaredTolerance||Math.Abs(result.FrontLowerSeamMm-180)>1e-9||Math.Abs(result.BackLowerSeamMm-195)>1e-9||result.SewingStatus!="unresolved"||result.ProductionAllowed)throw new Exception("local waist result");var cm=LocalWaistReview.Inspect(Contract.Model,"cm",true,true,true,"2",Contract.SampleInput("synthetic-base","cm"));if(cm.ToleranceMm!=20m||cm.DifferenceMm!=20m||cm.Comparison!=InputComparison.WithinDeclaredTolerance||cm.SewingStatus!="unresolved")throw new Exception("local tolerance units");var corrected=new Dictionary<string,string>(fields){["upper.waist"]="720"};var same=LocalWaistReview.Inspect(Contract.Model,"mm",true,true,true,"0",corrected);if(same.DifferenceMm!=0||same.SewingStatus!="unresolved")throw new Exception("false seam approval");foreach(var invalid in new[]{"","-1","NaN","10001"}){try{LocalWaistReview.Inspect(Contract.Model,"mm",true,true,true,invalid,fields);throw new Exception("invalid tolerance accepted");}catch(InvalidOperationException){}}try{LocalWaistReview.Inspect(Contract.Model,"mm",true,true,false,"0",fields);throw new Exception("reference assumption accepted");}catch(InvalidOperationException){}var w=new ResearchWindow();w.PrepareBlankFillForTest();if(!w.TryFillSample(()=>true))throw new Exception("local sample");w.PrepareLocalForTest();w.RunLocalReview();if(!w.StatusForTest.Contains("dikiş")||!w.StatusForTest.Contains("20"))throw new Exception("local correction guidance missing");w.EditForTest();if(w.StatusForTest.Contains("Üst − alt")||w.ConfirmedForTest)throw new Exception("stale local report");}
    static void VerifyUnits()
    {
        foreach(var t in new[]{"1,000","1.000","12,345","0,001"})if(ExplicitNumber.TryParse(t,out _))throw new Exception("ambiguous separator accepted");
        if(!ExplicitNumber.TryParse("0,0010",out var small)||small!=0.001m||!ExplicitNumber.TryParse(ExplicitNumber.Format(1.001m),out var formatted)||formatted!=1.001m)throw new Exception("explicit numeric rule");
        foreach(var key in new[]{"upper.waist","lower.frontWaist"}){var ambiguous=Contract.SampleInput("synthetic-base","mm");ambiguous[key]="1,000";try{Contract.Normalize(Contract.Model,"mm",true,true,ambiguous);throw new Exception("ambiguous form field accepted");}catch(InvalidOperationException){}}
        var partial=new ResearchWindow();partial.PrepareBlankFillForTest();partial.SetFieldForTest("upper.waist","999");partial.SetFieldForTest("upper.shoulderSlope","15");partial.SetFieldForTest("lower.frontWaistEase","0");partial.SetToleranceForTest("0,0010");partial.ConfirmUnitForTest=(_,_)=>true;partial.ChangeUnitForTest();
        if(partial.UnitForTest!="cm"||partial.FieldForTest("upper.waist")!="99.9"||partial.FieldForTest("upper.shoulderSlope")!="15"||partial.ToleranceForTest!="0.0001"||partial.FieldForTest("lower.frontWaist")!="")throw new Exception("partial unit conversion");
        partial.ResetUnitForTest();if(partial.UnitForTest!="mm"||partial.FieldForTest("upper.waist")!="999"||partial.ToleranceForTest!="0.0010")throw new Exception("unit roundtrip");
        var cancel=new ResearchWindow();cancel.PrepareFillForTest();cancel.SetToleranceForTest("0.01");var original=cancel.FieldsForTest;cancel.ConfirmUnitForTest=(_,_)=>false;cancel.ChangeUnitForTest();if(cancel.UnitForTest!="mm"||cancel.ToleranceForTest!="0.01"||original.Any(x=>cancel.FieldForTest(x.Key)!=x.Value))throw new Exception("unit cancel changed input");
        cancel.ConfirmUnitForTest=(_,_)=>{cancel.ChangeAndRestoreForTest();return true;};cancel.ChangeUnitForTest();if(cancel.UnitForTest!="mm"||original.Any(x=>cancel.FieldForTest(x.Key)!=x.Value))throw new Exception("stale unit conversion");
        cancel.ConfirmUnitForTest=(_,_)=>{cancel.ChangeModelAndRestoreForTest();return true;};cancel.ChangeUnitForTest();if(cancel.UnitForTest!="mm"||original.Any(x=>cancel.FieldForTest(x.Key)!=x.Value))throw new Exception("stale unit model");
        cancel.ConfirmUnitForTest=(_,_)=>{cancel.ChangeUnitForTest();return true;};cancel.ChangeUnitForTest();if(cancel.UnitForTest!="mm"||original.Any(x=>cancel.FieldForTest(x.Key)!=x.Value))throw new Exception("nested unit change");
        cancel.ConfirmUnitForTest=(_,_)=>true;cancel.UnitApplyForTest=i=>{if(i==3)throw new InvalidOperationException("injected");};cancel.ChangeUnitForTest();if(cancel.UnitForTest!="mm"||cancel.ToleranceForTest!="0.01"||original.Any(x=>cancel.FieldForTest(x.Key)!=x.Value))throw new Exception("unit rollback");
        cancel.ConfirmUnitForTest=(_,_)=>throw new InvalidOperationException("injected confirmation failure");cancel.ChangeUnitForTest();if(cancel.UnitForTest!="mm"||cancel.ToleranceForTest!="0.01"||original.Any(x=>cancel.FieldForTest(x.Key)!=x.Value))throw new Exception("unit confirmation failure");
        var invalid=new ResearchWindow();invalid.PrepareBlankFillForTest();invalid.SetFieldForTest("upper.waist","1,000");bool asked=false;invalid.ConfirmUnitForTest=(_,_)=>{asked=true;return true;};invalid.ChangeUnitForTest();if(asked||invalid.UnitForTest!="mm"||invalid.FieldForTest("upper.waist")!="1,000")throw new Exception("ambiguous conversion");
        var tinyInput=new ResearchWindow();tinyInput.PrepareBlankFillForTest();string tinyText="0."+new string('0',21)+"1";tinyInput.SetFieldForTest("upper.waist",tinyText);asked=false;tinyInput.ConfirmUnitForTest=(_,_)=>{asked=true;return true;};tinyInput.ChangeUnitForTest();if(asked||tinyInput.UnitForTest!="mm"||tinyInput.FieldForTest("upper.waist")!=tinyText)throw new Exception("unrepresentable conversion");
        var full=new ResearchWindow();full.PrepareBlankFillForTest();if(!full.TryFillSample(()=>true))throw new Exception("unit sample");full.PrepareLocalForTest();full.ConfirmUnitForTest=(_,_)=>true;full.ChangeUnitForTest();if(full.UnitForTest!="cm"||full.ConfirmedForTest||Contract.Validate(Contract.Model,"cm",true,true,full.FieldsForTest).Id!="synthetic-base")throw new Exception("full form conversion");
        var fields=Contract.SampleInput("synthetic-base","mm");fields["upper.waist"]="720.00004";var tiny=LocalWaistReview.Inspect(Contract.Model,"mm",true,true,true,"0.00001",fields);string dv=0.00004m.ToString("0.############################",System.Globalization.CultureInfo.CurrentCulture),tv=0.00001m.ToString("0.############################",System.Globalization.CultureInfo.CurrentCulture);if(tiny.Comparison!=InputComparison.OutsideDeclaredTolerance||!tiny.Text.Contains(dv)||!tiny.Text.Contains(tv))throw new Exception("rounded nonzero comparison");
